def nxt(v): return 1 if v==9 else v+1
def prv(v): return 9 if v==1 else v-1
B=A.copy()
# constraint propagation on zeros
known = B!=0
for _ in range(60):
    changed=False
    for i in range(23):
        for j in range(23):
            if known[i,j]: continue
            cands=[]
            if i>0 and j>0 and known[i-1,j-1]: cands.append(nxt(B[i-1,j-1]))
            if j>0 and known[i,j-1]: cands.append(nxt(B[i,j-1]))
            if j<22 and known[i,j+1]: cands.append(prv(B[i,j+1]))
            if i<22 and j<22 and known[i+1,j+1]: cands.append(prv(B[i+1,j+1]))
            if cands and len(set(cands))==1:
                B[i,j]=cands[0]; known[i,j]=True; changed=True
    if not changed: break
print("unknown cells:", [(i,j) for i in range(23) for j in range(23) if not known[i,j]][:40])
# verify full consistency of filled B
viol=[]
for i in range(23):
    for j in range(23):
        if j>0 and known[i,j] and known[i,j-1] and B[i,j]!=nxt(B[i,j-1]) and not (i==j and B[i,j]==B[i,j-1] and i>0):
            viol.append(('h',i,j))
        if i>0 and j>0 and known[i,j] and known[i-1,j-1] and B[i,j]!=nxt(B[i-1,j-1]):
            viol.append(('d',i,j))
print("violations:", viol[:20], len(viol))
for r in B: print(' '.join(map(str,r)))

def nxt(v): return 1 if v==9 else v+1
