for i in range(23):
    v = 2 if i==0 else 3
    for j in range(23):
        if j==0:
            M[i][j]=v
        elif j==i and i>0:
            M[i][j]=v  # stall: repeat previous
        else:
            v=nxt(v); M[i][j]=v
# verify against given nonzero cells
err=[(i,j,A[i,j],M[i][j]) for i in range(23) for j in range(23) if A[i,j] and A[i,j]!=M[i][j]]
print("mismatches on given cells:", len(err), err[:10])
print("zeros in M (should be none):", sum(r.count(0) for r in M))
